async () => {
 const learnerQuestion = "Std chuẩn là 20,6 Hz thì mọi F0 đúng phải nằm trong mean cộng trừ 20,6 Hz, phải không?";
 const route = await jev.choice({
  state: learnerQuestion,
  instructions: "Xác định khái niệm mà người học đang hiểu nhầm; unknown nếu không đủ thông tin.",
  criteria: {
   period_multiple: "Quan hệ giữa lag T, 2T, 3T và F0",
   reference_scope: "Sự khác nhau giữa chuẩn cả file và chuẩn từng khung",
   std_range: "Ý nghĩa của độ lệch chuẩn và khoảng mean ± std",
   unknown: "Không xác định được khái niệm"
  }
 });
 const category = route.value.choice;
 const probes = {
  period_multiple: {claim:"Mọi đỉnh ACF tại lag lớn đều phải chia lag cho 3.", evidence:"Một tín hiệu lặp tại T cũng giống tại 2T và 3T; chưa biết đỉnh được chọn đang là T hay 3T. Chia một lag T đúng cho 3 làm F0 tăng sai ba lần."},
  reference_scope: {claim:"Ba thống kê mean/std/count của file xác định duy nhất F0 chuẩn từng khung.", evidence:"LAB 3GT chỉ chứa mean, std và count của cả file. Hoán vị thứ tự các F0 giữ nguyên cả ba thống kê nhưng thay đổi giá trị gán cho thời điểm."},
  std_range: {claim:"Mọi F0 đúng phải nằm trong khoảng mean ± std.", evidence:"Std là căn trung bình bình phương khoảng cách tới mean. Nó đo độ phân tán, không định nghĩa giá trị nhỏ nhất/lớn nhất hay giới hạn bắt buộc của từng phần tử. LAB cung cấp mean/std của cả file, không có giới hạn theo khung."}
 };
 if (!Object.prototype.hasOwnProperty.call(probes, category)) {
  return {category, route:route.value, status:"needs_review", routeMeta:route.meta};
 }
 const review = await jev.check(probes[category]);
 return {category, route:route.value, chosenProbe:probes[category], review:review.value, routeMeta:route.meta, reviewMeta:review.meta};
}
